import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"Synth","description":"","frontmatter":{},"headers":[],"relativePath":"demos/SYNTH.md","filePath":"demos/SYNTH.md"}'),r={name:"demos/SYNTH.md"};function h(o,e,i,l,d,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="synth" tabindex="-1">Synth <a class="header-anchor" href="#synth" aria-label="Permalink to &quot;Synth&quot;">​</a></h1><p>The demo songs played wholly on llamatron&#39;s built-in synths, with no FluidSynth and no DAW. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#acid_rain">Acid House</a>: <code>acid_rain.yml</code></li><li><a href="#duck_blur">8-Bit Game Theme</a>: <code>duck_blur.yml</code></li><li><a href="#cartridge_quest">Chip Adventure Theme</a>: <code>cartridge_quest.yml</code></li><li><a href="#side_pocket">Chip Funk</a>: <code>side_pocket.yml</code></li><li><a href="#machine_room">Drum Machine Jam</a>: <code>machine_room.yml</code></li></ul><p><a id="acid_rain"></a></p><h2 id="acid-house-acid-rain-yml" tabindex="-1">Acid House: <code>acid_rain.yml</code> <a class="header-anchor" href="#acid-house-acid-rain-yml" aria-label="Permalink to &quot;Acid House: `acid_rain.yml`&quot;">​</a></h2><p>Acid house in A minor at 126 beats a minute, every part on the built-in synths, written to show <a href="./../synths/engines/OH3">Oh3</a>. The squelch is Oh3&#39;s saw through its Diode filter, deep and resonant, its Acid gate set to Modded so that a run of accents climbs higher. The lead is Oh3&#39;s square two octaves over it, and an octave higher still at the peak, to show the instrument&#39;s whole range. MechaDrum plays the synth kick, snare, hats and cowbell.</p><p>The squelch hardly changes its notes; what moves is its marks, and they are rare: two accents a bar, off the beat and after a rest, and one slide a bar into the octave jump. Every second bar moves its accents and adds a slide, and the last bar of each eight climbs through three accents, the turnaround. The lead is a two-bar call and answer whose long note is its peak. The intro is two bars, the second drop lifts everything a fourth, and the peak takes the lead an octave up.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/synth/acid_rain.yml" target="_blank" rel="noreferrer"><code>examples/synth/acid_rain.yml</code></a> · A minor · 126 BPM · 2:16 · 9 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">accents</th><th style="text-align:center;">slides</th><th style="text-align:center;">built-in synths</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS">✓</a></td><td style="text-align:center;"><a href="./../SYNTHS">✓</a></td></tr></tbody></table><p><a id="duck_blur"></a></p><h2 id="_8-bit-game-theme-duck-blur-yml" tabindex="-1">8-Bit Game Theme: <code>duck_blur.yml</code> <a class="header-anchor" href="#_8-bit-game-theme-duck-blur-yml" aria-label="Permalink to &quot;8-Bit Game Theme: `duck_blur.yml`&quot;">​</a></h2><p>A bright, fast 8-bit game theme in the manner of the DuckTales theme (Mark Mueller), as a console of the eighties played it, every part on the built-in synths: a square lead with a little vibrato, a two-oscillator chord stab, a triangle bass bouncing octaves, and MechaDrum&#39;s kick, snare and hats. The verse&#39;s busy patter of repeated notes is answered by short tags; the lift climbs in two parallel lines while its snare rolls into the chorus; and the chorus opens each half with two punchy notes and a high answer before a long running line, over the borrowed chords bVI and bVII rising to I. A stuttering bridge of calls and answers comes before the last two choruses. The chords of every scene come from the <a href="./../generators/CHORDS">Chords</a> generator on the chords and bass tracks.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/synth/duck_blur.yml" target="_blank" rel="noreferrer"><code>examples/synth/duck_blur.yml</code></a> · G major · 156 BPM · 1:57 · 11 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">progressions</th><th style="text-align:center;">built-in synths</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td><td style="text-align:center;"><a href="./../INSTRUMENTS">✓</a></td></tr></tbody></table><p><a id="cartridge_quest"></a></p><h2 id="chip-adventure-theme-cartridge-quest-yml" tabindex="-1">Chip Adventure Theme: <code>cartridge_quest.yml</code> <a class="header-anchor" href="#chip-adventure-theme-cartridge-quest-yml" aria-label="Permalink to &quot;Chip Adventure Theme: `cartridge_quest.yml`&quot;">​</a></h2><p>A home-computer adventure theme in D minor at 150 beats a minute, every sound on the <a href="./../synths/engines/SID">SID</a> engine, as one sound chip of the 1980s played it. The lead is a pulse wave whose width an LFO sweeps slowly through the Mod Matrix, with a second LFO adding vibrato. The arpeggio plays each chord as a single note, and the oscillator&#39;s Arpeggio steps it through root, fifth and octave fifty times a second, the chip composer&#39;s way of sounding a chord on one voice. A triangle plays the bass, the chip&#39;s noise wave the snare and hats, a triangle with a falling pitch the kick, and a ring-modulated triangle is a bell that answers the lead.</p><p>The verse and the chorus differ in every way a chip can make them differ. The verse sits low, on a two-bar motif stated four times with its ending changed, its chords two bars each, with no snare, a dark arpeggio and soft notes. The pre-chorus climbs a step a bar while a noise roll speeds up. The chorus jumps an octave to its hook, a chord a bar, a backbeat, a bright arpeggio and loud notes. The <a href="./../generators/PHRASING">Phrasing</a> generator shapes the lead&#39;s lines, each growing toward its long note and breathing after it.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/synth/cartridge_quest.yml" target="_blank" rel="noreferrer"><code>examples/synth/cartridge_quest.yml</code></a> · D minor · 150 BPM · 1:37 · 11 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">arpeggio</th><th style="text-align:center;">mod matrix</th><th style="text-align:center;">built-in synths</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../synths/engines/SID">✓</a></td><td style="text-align:center;"><a href="./../synths/MOD_MATRIX">✓</a></td><td style="text-align:center;"><a href="./../SYNTHS">✓</a></td></tr></tbody></table><p><a id="side_pocket"></a></p><h2 id="chip-funk-side-pocket-yml" tabindex="-1">Chip Funk: <code>side_pocket.yml</code> <a class="header-anchor" href="#chip-funk-side-pocket-yml" aria-label="Permalink to &quot;Chip Funk: `side_pocket.yml`&quot;">​</a></h2><p>Chip funk in E dorian at 104 beats a minute, every sound on the <a href="./../synths/engines/POCKET">Pocket</a> engine, a handheld game console&#39;s sound chip. Funk is in what is left out: everyone hits the one hard, every part is short and mostly rests, each fitting into the others&#39; holes, and the sixteenths swing only lightly. The snare&#39;s backbeat is answered by ghost notes, the bass plays short notes around rests, and the two pulse channels play the chords as stabs of two guide tones, mostly ghosts. It also shows the Mod Matrix&#39;s MIDI CC sources: a CC row sent as CC 74 rides the stabs&#39; cutoff through every beat, a wah, opens the bass&#39;s filter over the groove, and in the solo CC 1, the mod wheel, brings vibrato in late on each held note of the hook&#39;s pulse channel.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/synth/side_pocket.yml" target="_blank" rel="noreferrer"><code>examples/synth/side_pocket.yml</code></a> · E dorian · 104 BPM · 1:49 · 8 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">CC rows</th><th style="text-align:center;">mod matrix</th><th style="text-align:center;">built-in synths</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS">✓</a></td><td style="text-align:center;"><a href="./../synths/MOD_MATRIX">✓</a></td><td style="text-align:center;"><a href="./../SYNTHS">✓</a></td></tr></tbody></table><p><a id="machine_room"></a></p><h2 id="drum-machine-jam-machine-room-yml" tabindex="-1">Drum Machine Jam: <code>machine_room.yml</code> <a class="header-anchor" href="#drum-machine-jam-machine-room-yml" aria-label="Permalink to &quot;Drum Machine Jam: `machine_room.yml`&quot;">​</a></h2><p>A drum machine jam at 122 beats a minute on <a href="./../synths/engines/MECHADRUM">MechaDrum</a>, the built-in drum machine, each of its ten machines heard, with no lead and no chords: the groove is the music. The sixteenths swing a little, so the hats, the rim and the snare&#39;s ghost notes shuffle while the kick stays on the beat. The kick is loudest on the one, with a Hard Kick layered under it, the snare answers its backbeat with ghost notes, the rim plays a clave over two bars and the Karplus Drum a conga part on the root and the fifth. The closed and open hats are one machine in one choke group, so each closed hit cuts the open one short. The Acoustic Tom fills only the last bar of each eight, and the drop swaps the kick for the Hard Kick&#39;s broken electro pattern.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/synth/machine_room.yml" target="_blank" rel="noreferrer"><code>examples/synth/machine_room.yml</code></a> · C minor · 122 BPM · 1:39 · 8 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">drum machines</th><th style="text-align:center;">choke groups</th><th style="text-align:center;">built-in synths</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../synths/engines/MECHADRUM">✓</a></td><td style="text-align:center;"><a href="./../INSTRUMENTS">✓</a></td><td style="text-align:center;"><a href="./../SYNTHS">✓</a></td></tr></tbody></table>',30)])])}const p=t(r,[["render",h]]);export{u as __pageData,p as default};
